WITH base AS (SELECT id, full_name, email, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, ADD_MONTHS(hire_date, 6) AS hire_date_plus_months, FLOOR(salary) AS salary_whole FROM employees WHERE hire_date > TO_DATE('2023-04-15') AND job_title IS NOT NULL) SELECT level, manager_id FROM base EXCEPT ALL SELECT level, manager_id FROM employees WHERE salary >= 72000;
